class Solution:
    def numberOfSequence(self, n: int, sick: List[int]) -> int:
        MOD = 10**9 + 7

        infected_set = set(sick)
        dp = [0] * n

        dp[0] = 1 if 0 not in infected_set else 0
        dp[1] = 1 if 1 not in infected_set else dp[0]

        for i in range(2, n):
            if i not in infected_set and (i - 1) not in infected_set:
                dp[i] = (dp[i-2] + dp[i-1]) % MOD

        return dp[-1]
```

